import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'
import { StringColumn, BooleanColumn, IntegerColumn, DateTimeColumn } from '@servicenow/sdk/core'
// NOTE: wfa.subflow() is not supported in MVP - dataProcessingSubflow import removed
// import { dataProcessingSubflow } from './data-processing-subflow.now'

/**
 * Daily Data Processing Flow
 * Demonstrates: Using core actions with various input types and inline scripts for daily value assignment
 * NOTE: Original version used subflows, which are not supported in MVP. This version uses core actions instead.
 */
Flow(
    {
        $id: Now.ID['daily_data_processing_flow'],
        name: 'Daily Data Processing Flow',
        description: 'Daily automated data processing using the data processing subflow',
        runAs: 'system',
        flowPriority: 'HIGH',
        flowVariables: {
            dailyBatchId: StringColumn({
                label: 'Daily Batch ID',
                mandatory: true,
            }),
            processedToday: IntegerColumn({
                label: 'Items Processed Today',
                mandatory: true,
            }),
            lastProcessingTime: DateTimeColumn({
                label: 'Last Processing Time',
                mandatory: true,
            }),
            isWeekend: BooleanColumn({
                label: 'Is Weekend',
                mandatory: true,
            }),
            currentEnvironment: StringColumn({
                label: 'Current Environment',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.scheduled.daily,
        {
            $id: Now.ID['daily_trigger'],
            annotation: 'Runs daily at 9:00 AM for automated data processing',
        },
        {
            time: Time({ hours: 9, minutes: 0, seconds: 0 }),
        }
    ),
    (_params) => {
        // Inline script to set daily flow variables with current values
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_daily_values'],
                annotation: 'Set daily flow variables using inline script logic',
            },
            _params.flowVariables,
            {
                // Generate daily batch ID using simple template
                dailyBatchId: 'BATCH_DAILY_001',

                // Initialize processed count
                processedToday: 0,

                // Set current timestamp placeholder
                lastProcessingTime: '2024-01-01 09:00:00',

                // Inline logic to determine if today is weekend (defaulting to false for weekday processing)
                isWeekend: false,

                // Set current environment
                currentEnvironment: 'production',
            }
        )

        // Log the start of daily processing with inline values
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_daily_start'],
                annotation: 'Log daily processing start with assigned values',
            },
            {
                log_level: 'info',
                log_message: `Daily data processing started - Batch: ${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')}, Environment: ${wfa.dataPill(_params.flowVariables.currentEnvironment, 'string')}, Weekend: ${wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')}`,
            }
        )

        // Conditional processing based on weekend check (inline script logic)
        wfa.flowLogic.if(
            {
                $id: Now.ID['check_weekend'],
                condition: `${wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')}=true`,
                annotation: 'Check if today is weekend using inline assigned value',
            },
            () => {
                // Weekend processing with lower priority
                // NOTE: wfa.subflow() is not supported in MVP - using core actions instead
                // const weekendResult = wfa.subflow(...)

                // Log weekend processing start
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['weekend_processing'],
                        annotation: 'Process data with weekend configuration',
                    },
                    {
                        log_level: 'info',
                        log_message: `Weekend data processing started for batch ${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')} - Lower priority (3), Smaller batch size (50)`,
                    }
                )

                // Update flow variables with weekend processing results
                wfa.flowLogic.setFlowVariables(
                    {
                        $id: Now.ID['update_weekend_results'],
                        annotation: 'Update flow variables with weekend processing results',
                    },
                    _params.flowVariables,
                    {
                        processedToday: 150, // Simulated weekend processing count
                        lastProcessingTime: '2024-01-01 10:00:00',
                    }
                )

                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_processing_summary_34'],
                        annotation: 'Log weekend processing summary',
                    },
                    {
                        log_level: 'info',
                        log_message: `Weekend processing summary - Batch: ${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')}, Processed: ${wfa.dataPill(_params.flowVariables.processedToday, 'integer')}, Last Time: ${wfa.dataPill(_params.flowVariables.lastProcessingTime, 'string')}, Weekend: ${wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')}`,
                    }
                )
            }
        )

        wfa.flowLogic.else(
            {
                $id: Now.ID['weekday_processing'],
                annotation: 'Process data for weekday with higher priority',
            },
            () => {
                // Weekday processing with higher priority and larger batches
                // NOTE: wfa.subflow() is not supported in MVP - using core actions instead
                // const weekdayResult = wfa.subflow(...)

                // Log weekday processing start
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['weekday_data_processing'],
                        annotation: 'Process data with weekday configuration',
                    },
                    {
                        log_level: 'info',
                        log_message: `Weekday data processing started for batch ${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')} - High priority (1), Larger batch size (200), Environment: ${wfa.dataPill(_params.flowVariables.currentEnvironment, 'string')}`,
                    }
                )

                // Update flow variables with weekday processing results using inline calculations
                wfa.flowLogic.setFlowVariables(
                    {
                        $id: Now.ID['update_weekday_results'],
                        annotation: 'Update flow variables with weekday processing results and inline calculations',
                    },
                    _params.flowVariables,
                    {
                        processedToday: 1550, // Simulated weekday processing count (sum of active items: 500+300+750)
                        lastProcessingTime: '2024-01-01 17:00:00',
                        dailyBatchId: `${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')}_COMPLETED`,
                    }
                )

                // Send completion notification with inline script values
                wfa.action(
                    action.core.sendEmail,
                    {
                        $id: Now.ID['send_completion_notification'],
                        annotation: 'Send completion notification with processing summary',
                    },
                    {
                        ah_to: wfa.dataPill(_params.flowVariables.dailyBatchId, 'string'),
                        ah_subject: `Daily Data Processing Complete - 1234`,
                        ah_body: `
                            Daily data processing has been completed successfully.

                            Processing Details:
                            - Batch ID: 1234
                            - Environment: production
                            - Items Processed: 1550
                            - Processing Time: 2024-01-01 17:00:00
                            - Weekend Processing: false
                            - Processing completed at: 2024-01-01 17:00:00
                        `,
                        watermark_email: true,
                    }
                )
            }
        )

        // Log final processing summary with all inline assigned values
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_processing_summary'],
                annotation: 'Log final processing summary with all assigned values',
            },
            {
                log_level: 'info',
                log_message: `Daily processing summary - Batch: ${wfa.dataPill(_params.flowVariables.dailyBatchId, 'string')}, Processed: ${wfa.dataPill(_params.flowVariables.processedToday, 'integer')}, Last Time: ${wfa.dataPill(_params.flowVariables.lastProcessingTime, 'string')}, Weekend: ${wfa.dataPill(_params.flowVariables.isWeekend, 'boolean')}`,
            }
        )
    }
)
